---入口点击回调
function ActivityNightCatNode:EntryOnClickHandler()
    local t = checkTable(self._activityDojo.unlock)
    if table.count(t) > 0 then
        local vo = t[1]
        local isUnlock = GameUtils.IsUnlockedSingle(vo.targetType, vo.targetNum, vo.targetId)
        if not isUnlock then
            local err = GameUtils.GetUnlockDescr(vo.targetType, vo.targetNum, vo.targetId)
            GameUtils.Toast(err)
            return
        end
    end
    xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(self._activityDojo.id)))
    UIModule.OpenDialog({ id = Constants.UITypeIds.ActivityNightCatDialog, parameters = {activityId = self._activityDojo.id}},
            {{id = Constants.UITypeIds.UIActivityMainDialog}})
end
--endregion handler

